-- ============================================
-- 数据验证查询 (导入后执行)
-- ============================================
-- 以下查询用于验证数据导入是否成功

-- 1. 检查各表记录数
SELECT 'users' AS table_name, COUNT(*) AS count FROM users
UNION ALL SELECT 'merchants', COUNT(*) FROM merchants
UNION ALL SELECT 'stores', COUNT(*) FROM stores
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'orders', COUNT(*) FROM orders;

-- 2. 检查外键关联 - 订单关联的用户是否存在
SELECT COUNT(*) AS orphan_orders
FROM orders o
LEFT JOIN users u ON o.user_id = u.id
WHERE u.id IS NULL;
-- 期望结果: 0 (如果大于0说明有孤立订单)

-- 3. 检查订单金额计算
SELECT order_no, total_product_price, total_discount_amount, final_paid_price,
       (total_product_price - total_discount_amount) AS calculated_price,
       (final_paid_price - (total_product_price - total_discount_amount)) AS diff
FROM orders
WHERE ABS(final_paid_price - (total_product_price - total_discount_amount)) > 0.01
LIMIT 10;
-- 期望结果: 0 行 (如果有结果说明金额计算有误)

-- 4. 检查时间逻辑 - 订单时间顺序
SELECT COUNT(*) AS invalid_time_orders
FROM orders
WHERE (payment_time IS NOT NULL AND payment_time < created_time)
   OR (completion_time IS NOT NULL AND completion_time < payment_time);
-- 期望结果: 0 (如果大于0说明时间逻辑有误)

-- 5. 检查积分账户余额
SELECT pa.id, pa.owner_type, pa.available_points,
       COALESCE(SUM(pb.remaining_points), 0) AS calculated_points,
       (pa.available_points - COALESCE(SUM(pb.remaining_points), 0)) AS diff
FROM points_account pa
LEFT JOIN points_batch pb ON pa.owner_id = pb.owner_id AND pa.owner_type = pb.owner_type AND pb.is_deleted = 0
GROUP BY pa.id
HAVING ABS(diff) > 0
LIMIT 10;
-- 期望结果: 0 行 (如果有结果说明积分余额不一致)

